// src/ui/settings.js
var cyc = (arr, v10, d10) => arr[(arr.indexOf(v10) + d10 + arr.length) % arr.length];
var SettingsScreen = class {
  constructor(app2, ctx, back) {
    this.app = app2;
    this.ctx = ctx;
    this.back = back;
    const s10 = app2.settings, ap2 = () => app2.applySettings(ctx);
    const pct = (k10, step2 = 0.1) => ({ slider: true, value: () => Math.round(s10[k10] * 100) + "%", frac: () => s10[k10], onLeft: () => {
      s10[k10] = Math.max(0, Math.round((s10[k10] - step2) * 100) / 100);
      ap2();
    }, onRight: () => {
      s10[k10] = Math.min(1, Math.round((s10[k10] + step2) * 100) / 100);
      ap2();
    }, onSet: (f10) => {
      s10[k10] = Math.round(f10 * 20) / 20;
      ap2();
    } });
    const tog = (k10, a10 = "ON", b10 = "OFF") => ({ value: () => s10[k10] ? a10 : b10, onLeft: () => {
      s10[k10] = !s10[k10];
      ap2();
    }, onRight: () => {
      s10[k10] = !s10[k10];
      ap2();
    }, onSelect: () => {
      s10[k10] = !s10[k10];
      ap2();
    } });
    const choice = (k10, arr, lab = (x10) => x10.toUpperCase()) => ({ value: () => lab(s10[k10]), onLeft: () => {
      s10[k10] = cyc(arr, s10[k10], -1);
      ap2();
    }, onRight: () => {
      s10[k10] = cyc(arr, s10[k10], 1);
      ap2();
    }, onSelect: () => {
      s10[k10] = cyc(arr, s10[k10], 1);
      ap2();
    } });
    this.items = [
      { label: "MUSIC", ...pct("music") },
      { label: "SOUND", ...pct("sfx") },
      { label: "VOICES", ...pct("voices") },
      { label: "GLYPHS", ...choice("glyphs", ["ps", "xbox"], (x10) => x10 === "ps" ? "PLAYSTATION" : "XBOX") },
      { label: "AIM ASSIST", ...choice("aim", ["off", "low", "high"]) },
      { label: "CURSOR SPEED", slider: true, value: () => s10.cursor.toFixed(0), frac: () => (s10.cursor - 4) / 16, onLeft: () => {
        s10.cursor = Math.max(4, s10.cursor - 1);
        ap2();
      }, onRight: () => {
        s10.cursor = Math.min(20, s10.cursor + 1);
        ap2();
      }, onSet: (f10) => {
        s10.cursor = Math.round(4 + f10 * 16);
        ap2();
      } },
      { label: "RUMBLE", ...tog("rumble") },
      { label: "GIFT", ...tog("giftToggle", "TOGGLE", "HOLD") },
      { label: "LOOK", ...choice("look", ["default", "crisp", "noir", "warm"]) },
      { label: "PIXEL SIZE", ...choice("pixel", [1, 2], (x10) => x10 + "X") },
      { label: "SCREEN SHAKE", ...tog("shake") },
      { label: "REDUCE FLASHES", ...tog("flashes", "OFF", "ON") },
      { label: "TEXT SPEED", ...choice("textSpeed", [1, 2, 3], (x10) => ["SLOW", "NORMAL", "FAST"][x10 - 1]) },
      { label: "DIFFICULTY", ...choice("difficulty", ["intern", "resident", "attending"]) },
      { label: "FULLSCREEN", value: () => typeof document !== "undefined" && document.fullscreenElement ? "ON" : "OFF", onSelect: () => {
        try {
          if (document.fullscreenElement) document.exitFullscreen();
          else document.documentElement.requestFullscreen();
        } catch {
        }
      } },
      { label: "RESET TO DEFAULTS", onSelect: () => {
        app2.resetSettings(ctx);
      } },
      { label: "BACK", onSelect: () => this.close() }
    ];
    this.items[11].value = () => s10.flashes ? "ON" : "OFF";
    this.items[11].onLeft = this.items[11].onRight = this.items[11].onSelect = () => {
      s10.flashes = !s10.flashes;
    };
    this.menu = new Menu(this.items);
    this.scroll = 0;
  }
  close() {
    this.app.flush();
    this.back?.();
  }
  update(nav, dt2) {
    const r10 = this.menu.update(nav, this.app, dt2, this.ctx.audio);
    if (r10 === "back") this.close();
  }
  draw(hud) {
    hud.rect(0, 0, hud.width, hud.height, "night");
    ctext(hud, 6, "SETTINGS", { scale: 2, color: "sand" });
    const n10 = this.items.length, vis = 11, i10 = this.menu.i;
    this.scroll = Math.max(0, Math.min(n10 - vis, i10 - 5));
    const saved = this.menu.items;
    this.menu.items = this.items.slice(this.scroll, this.scroll + vis);
    const oi2 = this.menu.i;
    this.menu.i = i10 - this.scroll;
    this.menu.draw(hud, 30, { rowH: 20 });
    this.menu.items = saved;
    this.menu.i = oi2;
    const rects = this.menu.rects;
    this.menu.rects = [];
    rects.forEach((q10, k10) => {
      this.menu.rects[k10 + this.scroll] = q10;
    });
    prompts(hud, this.app, [{ act: "nav", label: "MOVE" }, { act: "confirm", label: "CHANGE" }, { act: "back", label: "BACK" }], "center", hud.height - 14);
  }
};

