function recordResult(save, opId, res2) {
  const c10 = save.cleared[opId] ??= { best: null, bestScore: 0, plays: 0, pristine: false };
  c10.best = betterRank(c10.best, res2.rank);
  c10.bestScore = Math.max(c10.bestScore, res2.total);
  c10.plays++;
  c10.pristine = c10.pristine || res2.pristine;
  const idx = CAMPAIGN.findIndex((s10) => s10.op === opId);
  if (idx >= 0 && idx + 1 > save.next) save.next = idx + 1;
  if (opId === "op3") save.quietOn = true;
  return save;
}
