var TAGLINE = "Second Helpings";

// src/stages/menu.js
init_config();
var IDLE_MS = 1e4;
var MenuStage = class {
  name = "Menu";
  constructor(a10 = {}) {
    this.a = a10;
  }
  async setup(ctx) {
    this.ctx = ctx;
    this.t = 0;
    ctx.engine.setLook(LOOK(0.9, 0.55, 0));
    this.screen = this.a.screen || "title";
    const { ensureKit: ensureKit2 } = await Promise.resolve().then(() => (init_sets(), sets_exports));
    await ensureKit2();
    this.set = buildSet(ctx, "or7");
    ctx.engine.sun.intensity = 0.25;
    ctx.engine.ambient.intensity = 0.22;
    this.cam = new ate.Vector3(0, 4.6, 8.6);
    app.director.start(ctx, "title", 0);
    this.swallow = this.a.swallow ? 0.6 : 0;
    this.idleStart = performance.now();
    this.sub = null;
    this.logI = 0;
    this.aboutI = 0;
    this.buildMain(ctx);
    app.applySettings(ctx);
    ctx.input.preventKeys.add("Tab");
    if (typeof document !== "undefined" && ctx.engine.container) ctx.engine.container.style.cursor = "";
    this.lastAct = app.devices.activity;
    app.attractActive = false;
  }
  cameraTarget() {
    return new ate.Vector3(0, 1.6, 0);
  }
  status() {
    return `menu ${this.screen}`;
  }
  buildMain(ctx) {
    const s10 = app.save, has = s10.next > 0 && s10.next < CAMPAIGN.length;
    const items = [];
    if (has) items.push({ label: "CONTINUE", onSelect: () => this.continueGame(ctx) });
    items.push({ label: has ? "NEW SHIFT" : "ON CALL", onSelect: () => this.openDiff(ctx) });
    items.push({ label: "OPERATING LOG", onSelect: () => this.screen = "log" }, { label: "CONSULT", onSelect: () => go2.consult(ctx) }, { label: "SETTINGS", onSelect: () => {
      this.screen = "settings";
      this.sub = new SettingsScreen(app, ctx, () => {
        this.screen = "main";
        this.sub = null;
      });
    } }, { label: "ABOUT", onSelect: () => {
      this.screen = "about";
      this.aboutI = 0;
    } });
    this.main = new Menu(items);
  }
  openDiff(ctx) {
    this.screen = "diff";
    const pick2 = (d10) => {
      app.save.difficulty = d10;
      app.settings.difficulty = d10;
      app.save.next = 0;
      app.save.quietOn = false;
      app.flush();
      this.startShift(ctx);
    };
    this.diff = new Menu([{ label: "INTERN", value: "TIME +40%, DRAIN -40%, TWO CODE BLUE SAVES", onSelect: () => pick2("intern") }, { label: "RESIDENT", value: "THE INTENDED SHIFT", onSelect: () => pick2("resident") }, { label: "ATTENDING", value: "TIME -20%, DRAIN +30%, NO HINTS", onSelect: () => pick2("attending") }]);
    this.diff.i = 1;
  }
  startShift(ctx) {
    app.save.next = 0;
    go2.story(ctx, "ep1", { next: () => go2.briefing(ctx, "op1") });
  }
  continueGame(ctx) {
    const st2 = CAMPAIGN[Math.min(app.save.next, CAMPAIGN.length - 1)];
    if (st2.op) go2.story(ctx, st2.scene, { next: () => go2.briefing(ctx, st2.op) });
    else go2.story(ctx, st2.scene, { next: () => go2.credits(ctx) });
  }
  update(ctx, dt2) {
    const hud = ctx.hud, dev = app.devices;
    dev.poll(dt2, ctx);
    let nav = dev.nav;
    this.t += dt2;
    this.set.update(dt2, this.t);
    const cam = ctx.camera.camera;
    cam.position.set(Math.sin(this.t * 0.15) * 1.2, 3.8 + Math.sin(this.t * 0.1) * 0.3, 8.8);
    cam.fov = 46;
    cam.updateProjectionMatrix();
    cam.lookAt(0, 1.5, 0);
    cam.updateMatrixWorld?.(true);
    if (this.swallow > 0) {
      this.swallow -= dt2;
      if (this.swallow > 0 || nav.any) {
        nav = dev.emptyNav();
      }
    }
    if (dev.activity !== this.lastAct) {
      this.lastAct = dev.activity;
      this.idleStart = performance.now();
    }
    if (performance.now() - this.idleStart > IDLE_MS && !this.noAttract) {
      app.attractActive = true;
      return go2.attractStart(ctx);
    }
    hud.clear();
    const w10 = hud.width, h10 = hud.height;
    this.nav = nav;
    if (this.screen === "title") this.drawTitle(ctx, hud, nav, dt2);
    else if (this.screen === "main") {
      this.drawHeader(hud);
      const r10 = this.main.update(nav, app, dt2, ctx.audio);
      this.main.draw(hud, 108, { rowH: 24 });
      prompts(hud, app, [{ act: "nav", label: "MOVE" }, { act: "confirm", label: "SELECT" }], "center", h10 - 14);
      if (r10 === "back") this.screen = "title";
    } else if (this.screen === "diff") {
      this.drawHeader(hud);
      ctext(hud, 100, "CHOOSE A DIFFICULTY", { color: "sand" });
      const r10 = this.diff.update(nav, app, dt2, ctx.audio);
      this.diff.draw(hud, 124, { rowH: 26 });
      prompts(hud, app, [{ act: "confirm", label: "BEGIN" }, { act: "back", label: "BACK" }], "center", h10 - 14);
      if (r10 === "back") this.screen = "main";
    } else if (this.screen === "settings") {
      this.sub.update(nav, dt2);
      this.sub.draw(hud);
    } else if (this.screen === "log") this.drawLog(ctx, hud, nav);
    else if (this.screen === "about") this.drawAbout(ctx, hud, nav);
  }
  drawHeader(hud) {
    ctext(hud, 20, TITLE, { scale: 3, color: "white" });
    ctext(hud, 50, TAGLINE.toUpperCase(), { color: "sand" });
    hud.rect(0, 0, hud.width, 6, "ink");
  }
  drawTitle(ctx, hud, nav, dt2) {
    const w10 = hud.width, h10 = hud.height;
    hud.rect(0, 0, w10, 30, "ink");
    hud.rect(0, h10 - 50, w10, 50, "ink");
    ekg(hud, 40, 70, w10 - 80, 40, this.t, 1.1, "lime", 0);
    ctext(hud, 86, TITLE, { scale: 4, color: "white" });
    ctext(hud, 120, TAGLINE.toUpperCase(), { scale: 1, color: "sand" });
    ctext(hud, 20, "A SURGICAL DRAMA IN PIXEL ART", { color: "mist" });
    if ((this.t * 1.6 | 0) % 2 === 0) prompts(hud, app, [{ act: "any", label: "PRESS TO BEGIN" }], "center", h10 - 40);
    ctext(hud, h10 - 12, "THE TRUTH, STAT.", { color: "slate" });
    if (nav.any && nav.confirm || nav.click || nav.any && !nav.hover) {
      ctx.audio.play("uiOk");
      this.screen = "main";
    }
  }
  drawLog(ctx, hud, nav) {
    const w10 = hud.width, h10 = hud.height;
    hud.rect(0, 0, w10, h10, "night");
    ctext(hud, 8, "OPERATING LOG", { scale: 2, color: "sand" });
    if (nav.x) {
      this.logI = (this.logI + nav.x + OPS.length) % OPS.length;
      ctx.audio.play("uiMove");
    }
    if (nav.tabL) this.logI = (this.logI + OPS.length - 1) % OPS.length;
    if (nav.tabR) this.logI = (this.logI + 1) % OPS.length;
    const op11 = OPS[this.logI], c10 = app.save.cleared[op11.id], un2 = isUnlocked(app.save, op11.id), cw2 = 300, cx2 = Math.round((w10 - cw2) / 2);
    hud.rect(cx2 - 2, 36, cw2 + 4, 190, "slate");
    hud.rect(cx2, 38, cw2, 186, "white");
    hud.text(cx2 + 10, 46, `OP ${this.logI + 1}`, { color: "red", shadow: false });
    hud.text(cx2 + 10, 58, op11.title, { color: "ink", scale: 2, shadow: false });
    if (un2) {
      hud.text(cx2 + 10, 82, op11.patient.name, { color: "navy", shadow: false });
      wrap(hud, op11.patient.hook, cw2 - 24).slice(0, 3).forEach((l10, i10) => hud.text(cx2 + 10, 94 + i10 * 10, l10, { color: "ink", shadow: false }));
      if (c10) {
        hud.text(cx2 + cw2 - 70, 50, c10.best, { scale: 5, color: { S: "sand", A: "lime", B: "sky", C: "orange" }[c10.best], shadow: "ink" });
        hud.text(cx2 + 10, 132, `BEST SCORE ${c10.bestScore}   PLAYS ${c10.plays}`, { color: "navy", shadow: false });
        wrap(hud, op11.patient.followUp[c10.best] || op11.patient.followUp.C, cw2 - 24).slice(0, 3).forEach((l10, i10) => hud.text(cx2 + 10, 148 + i10 * 10, l10, { color: "ink", shadow: false }));
        if (c10.pristine) hud.text(cx2 + 10, 184, "PRISTINE", { color: "sand", shadow: "ink" });
      } else hud.text(cx2 + 10, 132, "NOT YET OPERATED ON.", { color: "mist", shadow: false });
      hud.text(cx2 + 10, 205, "PRESS TO REPLAY THIS OPERATION", { color: "green", shadow: false });
    } else {
      hud.text(cx2 + 10, 100, "LOCKED. FINISH THE PREVIOUS SHIFT.", { color: "red", shadow: false });
    }
    ctext(hud, 232, `< ${this.logI + 1} / ${OPS.length} >`, { color: "white" });
    prompts(hud, app, [{ act: "nav", label: "FLIP" }, { act: "confirm", label: "REPLAY" }, { act: "back", label: "BACK" }], "center", h10 - 14);
    if (nav.back || nav.rclick) {
      this.screen = "main";
      ctx.audio.play("uiBack");
    }
    if ((nav.confirm || nav.click) && un2) go2.briefing(ctx, op11.id, { replay: true });
  }
  drawAbout(ctx, hud, nav) {
    const w10 = hud.width, h10 = hud.height, pages = ["SOURCE INFORMATION", "TESTING FEEDBACK", "ENGINE FEEDBACK", "PROMPT FEEDBACK", "CREDITS"];
    hud.rect(0, 0, w10, h10, "night");
    ctext(hud, 6, "ABOUT", { scale: 2, color: "sand" });
    if (nav.x) {
      this.aboutI = (this.aboutI + nav.x + 5) % 5;
      ctx.audio.play("uiMove");
      this.aboutScroll = 0;
    }
    if (nav.tabL) this.aboutI = (this.aboutI + 4) % 5;
    if (nav.tabR) this.aboutI = (this.aboutI + 1) % 5;
    ctext(hud, 28, `< ${pages[this.aboutI]} >`, { color: "white", scale: 1 });
    const lines = [];
    const B11 = ABOUT;
    if (this.aboutI === 0) for (const [k10, v10] of B11.source) {
      lines.push({ t: k10, c: "sand" });
      wrap(hud, v10, w10 - 60).forEach((l10) => lines.push({ t: l10, c: "white" }));
    }
    else if (this.aboutI === 4) for (const l10 of B11.credits) wrap(hud, l10 || " ", w10 - 60).forEach((x10) => lines.push({ t: x10, c: "white" }));
    else {
      const arr = [B11.testing, B11.engine, B11.prompt][this.aboutI - 1];
      for (const [q10, a10] of arr) {
        wrap(hud, q10, w10 - 60).forEach((l10) => lines.push({ t: l10, c: "sand" }));
        wrap(hud, a10, w10 - 60).forEach((l10) => lines.push({ t: l10, c: "white" }));
        lines.push({ t: " ", c: "white" });
      }
    }
    this.aboutScroll = this.aboutScroll || 0;
    const vis = 17;
    if (nav.y) this.aboutScroll = Math.max(0, Math.min(Math.max(0, lines.length - vis), this.aboutScroll + nav.y * 3));
    if (nav.wheel) this.aboutScroll = Math.max(0, Math.min(Math.max(0, lines.length - vis), this.aboutScroll + Math.sign(nav.wheel) * 3));
    lines.slice(this.aboutScroll, this.aboutScroll + vis).forEach((l10, i10) => hud.text(30, 44 + i10 * 12, l10.t, { color: l10.c }));
    if (lines.length > vis) bar(hud, w10 - 16, 44, 4, 200, this.aboutScroll / Math.max(1, lines.length - vis), "sand");
    prompts(hud, app, [{ act: "nav", label: "PAGE / SCROLL" }, { act: "back", label: "BACK" }], "center", h10 - 14);
    if (nav.back || nav.rclick) {
      this.screen = "main";
      ctx.audio.play("uiBack");
    }
  }
  dispose() {
  }
};

