    await ensureKit2();
    this.set = buildSet(ctx, this.scene.set);
    if (this.scene.id === "end" || this.scene.set === "ward") {
      this.set.rain?.removeFromParent?.();
      this.set.rain = null;
    }
    this.speaker = new Speaker(app);
    this.busts = {};
