    const m10 = new ate.Mesh(new ate.BoxGeometry(14, 8, 0.4), (await Promise.resolve().then(() => (init_pixel_engine(), pixel_engine_exports))).toonMaterial(2764616));
    m10.position.set(BX2, 1.6, -3);
    ctx.scene.add(m10);
    this.backdrop = m10;
    ctx.lights.request({ position: [BX2 + 2, 3.6, 4], color: 16773344, intensity: 10, radius: 12, priority: 9 });
    ctx.lights.request({ position: [BX2 - 3, 2.4, 3], color: 9089279, intensity: 5, radius: 10, priority: 8 });
    this.shotWide = this.set.shots.wide;
    this.mode = "wide";
